@pytest.mark.parametrize( "case,depth,minimum", [ ("weighted", 1, None), ("d2", 1, None), ("d2", 2, 1), ("conflict", 0, None), ("conflict", 2, None), ], ) @pytest.mark.parametrize("mode,damping", [("ordinary", 0), ("natural", 0), ("natural", 0.25)]) @pytest.mark.parametrize("update", ["joint", "forward", "reverse"]) @pytest.mark.parametrize("fixed,rate", [(True, 0.1), (False, 8.0)]) def test_frozen_three_round_transactions(case, depth, minimum, mode, damping, update, fixed, rate): initial, expected = rounds( case, depth=depth, minimum=minimum, mode=mode, damping=damping, update=update, fixed=fixed, rate=rate, ) with ExecutionContext() as context: run, train, validation, information = start(context, case) state = run.initialize() close(raw(context, run, state), np.broadcast_to(initial, train.offset.shape)) for ref in expected: before = state terms = grow( run, state, ref["channels"], depth=depth, mode=mode, damping=damping, information=information if minimum is not None else None, ) for term, nodes in zip(terms, ref["nodes"], strict=True): assert [None if f == -1 else (f, t, m) for f, t, m, _, _ in term.tree.topology] == [ n["key"] for n in nodes ] close(trees.export(run.ops, term.tree).value[:, 0], [n["value"] for n in nodes]) coefficients = [] for j in range(1 if fixed else 6): coefficient = rate * 0.5**j coefficients.append(coefficient) metrics = dict(context.metrics) proposal = run.propose_terms(state, terms, coefficient=coefficient) assert context.metrics["upload_bytes"] == metrics["upload_bytes"] accept = fixed or proposal.loss < state.loss updated = run.resolve(state, proposal, accept=accept) run.release(proposal) if accept: run.release(state) state = updated break assert updated is state for term in terms: run.ops.release(term.tree) > assert tuple(coefficients) == tuple(a[0] for a in ref["attempts"]) E assert (8.0, 4.0) == (8.0, 4.0, 2.....0, 0.5, 0.25) E E Right contains 4 more items, first extra item: 2.0 E Use -v to get more diff
